import {
  Platform,
  Share,
  StyleSheet,
  TouchableOpacity,
  View,
} from 'react-native';
import {useState} from 'react';
import {Icon} from '@ui-kitten/components';
import ModalConfirmCM from '../../../../../../components/ModalConfirm';
import {useTranslation} from 'react-i18next';
import {Color, Font} from '../../../../../../../constants';
import ExpandIssueReceipt from '../expand-issue-receipt';
import {ReleaseReceipt} from '../../helper';
import RNFS from 'react-native-fs';
import Toast from 'react-native-toast-message';
import ReactNativeBlobUtil from 'react-native-blob-util';
import {getConfig} from '../../../../../../../services/httpClient';
import TextCM from '../../../../../../components/Text';
import {CommonUtils} from '../../../../../../../utils';
type Props = {
  item: ReleaseReceipt;
};

const IssueReceiptItem = ({item}: Props) => {
  const {t} = useTranslation();

  const [isExpand, setIsExpand] = useState(false);
  const toggleExpand = () => setIsExpand(!isExpand);
  const [openModalDownload, setOpenModalDownload] = useState(false);

  const handleDownloadAttach = async (
    data: ReleaseReceipt & {keyName?: string; notionId?: string},
  ) => {
    try {
      let fileName: string = (data as any).fileName;

      const toFile = `${
        Platform.OS === 'android'
          ? RNFS.DownloadDirectoryPath
          : RNFS.DocumentDirectoryPath
      }/${new Date().getTime()}_${fileName}`;
      if (data.bucketName) {
        await downloadFileWithBucketName(
          toFile,
          data.bucketName,
          data.keyName,
          data.beanName,
        );
      } else {
        await downloadFileWithNoBucketName(data?.name, toFile);
      }
    } catch (error) {
    } finally {
      setOpenModalDownload(false);
    }
  };

  const downloadFileWithBucketName = async (
    toFile: string,
    bucket: string,
    keyName: string,
    beanName: string,
  ) => {
    try {
      Toast.show({
        type: 'info',
        text1: t('CM.noti'),
        text2: t('CM.pleaseWait'),
      });
      const dataBase64 = await ReactNativeBlobUtil.config({
        path: toFile,
      })
        .fetch(
          'GET',
          `${
            getConfig().BASE_URL
          }/services/eintelligent/api/s3/download?bucket=${bucket}&keyName=${keyName}&beanName=${beanName}`,
        )
        .then(res => {
          let status = res.info().status;
          if (status == 200) {
            let base64Str = res.path();
            return base64Str;
          } else return null;
        })
        .catch(() => null);
      if (dataBase64) {
        try {
          // await RNFS.writeFile(toFile, dataBase64, 'base64');
        } catch (error) {
          console.error(error);
        }
        if (Platform.OS === 'ios') {
          const dataShare = await Share.share({
            url: toFile,
          });
          if (dataShare.action == Share.dismissedAction) {
            Toast.show({
              type: 'error',
              text1: t('CM.noti'),
              text2: t('CM.downloadFail'),
            });
          } else {
            Toast.show({
              type: 'success',
              text1: t('CM.noti'),
              text2: t('CM.downloadSuccess'),
            });
          }
        } else {
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('CM.downloadSuccess'),
          });
        }
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.downloadFail'),
        });
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.downloadFail'),
      });
    }
  };

  const downloadFileWithNoBucketName = async (url: string, toFile: string) => {
    try {
      Toast.show({
        type: 'info',
        text1: t('CM.noti'),
        text2: t('CM.pleaseWait'),
      });
      const dataBase64 = await ReactNativeBlobUtil.fetch('GET', url)
        .then(res => {
          let status = res.info().status;
          if (status == 200) {
            let base64Str = res.base64();
            return base64Str;
          } else return null;
        })
        .catch(() => null);
      if (dataBase64) {
        try {
          await RNFS.writeFile(toFile, dataBase64, 'base64');
        } catch (error) {
          console.error(error);
        }
        if (Platform.OS === 'ios') {
          const dataShare = await Share.share({
            url: toFile,
          });
          if (dataShare.action == Share.dismissedAction) {
            Toast.show({
              type: 'error',
              text1: t('CM.noti'),
              text2: t('CM.downloadFail'),
            });
          } else {
            Toast.show({
              type: 'success',
              text1: t('CM.noti'),
              text2: t('CM.downloadSuccess'),
            });
          }
        } else {
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('CM.downloadSuccess'),
          });
        }
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.downloadFail'),
        });
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.downloadFail'),
      });
    }
  };

  return (
    <View key={item.id}>
      <TouchableOpacity
        style={styles.documentItem}
        onPress={() => toggleExpand()}>
        <View style={styles.documentRow}>
          <View style={styles.iconTitleContainer}>
            <View style={styles.iconContainer}>
              <Icon
                name={isExpand ? 'chevron-down' : 'chevron-right'}
                fill={'#C83A1B'}
                width={12}
                height={12}
              />
            </View>
            <TextCM numberOfLines={1} style={styles.documentTitle}>
              {CommonUtils.truncateText(item.fileName, 25)}
            </TextCM>
          </View>
          <TouchableOpacity
            style={styles.trashIcon}
            onPress={() => setOpenModalDownload(true)}>
            <Icon name="download" width={16} height={16} fill={Color.Black} />
          </TouchableOpacity>
        </View>
      </TouchableOpacity>
      {isExpand && <ExpandIssueReceipt item={item} />}

      <ModalConfirmCM
        type="info"
        title={t('CM.downloadFile')}
        content={t('BLDT.down_attachment_question')}
        onClose={() => setOpenModalDownload(false)}
        isVisible={openModalDownload}
        labelCancel={t('CM.back')}
        labelConfirm={t('CM.confirm')}
        onConfirm={() => handleDownloadAttach(item)}
      />
    </View>
  );
};
export default IssueReceiptItem;

const styles = StyleSheet.create({
  documentItem: {
    paddingVertical: 12,
  },
  documentRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  iconTitleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    flex: 1,
    columnGap: 8,
  },
  iconContainer: {
    borderWidth: 1,
    width: 14,
    height: 14,
    borderColor: '#C83A1B',
    borderRadius: 30,
    justifyContent: 'center',
    alignItems: 'center',
  },
  documentTitle: {
    fontSize: 13,
    fontFamily: Font.InterMedium500,
    color: '#00204DE5',
    flex: 1,
  },
  trashIcon: {
    padding: 4,
  },
});
