import React, {useMemo} from 'react';
import {Federated} from '@callstack/repack/client';
import SplashScreen from '../../../../components/Splash';
import {useNavigation, useRoute} from '@react-navigation/native';
import ErrorBoundary from '../../../../components/ErrorBoudary';

const CreateTicketScreen = () => {
  const route = useRoute<any>();
  const navigation = useNavigation();
  const actionTicketFrom = route?.params?.actionTicketFrom || 'eBLDT';
  const ComponentCM = useMemo(() => {
    return React.lazy(() =>
      Federated.importModule('eRequest', `./${'createTicket'}`),
    );
  }, []);
  return (
    <ErrorBoundary name="" navigation={navigation}>
      <React.Suspense fallback={<SplashScreen app={''} />}>
        <ComponentCM {...route?.params} actionTicketFrom={actionTicketFrom} />
      </React.Suspense>
    </ErrorBoundary>
  );
};

export default CreateTicketScreen;
