import {SafeAreaView} from 'react-native-safe-area-context';
import HeaderCM from '../../../../components/Header/HeaderCM';
import {View} from 'react-native';
import React from 'react';
import styles from './styles';
import {Federated} from '@callstack/repack/client';
import SplashScreen from '../../../../components/Splash';
import {useNavigation, useRoute} from '@react-navigation/native';
import {useTranslation} from 'react-i18next';
import ErrorBoundary from '../../../../components/ErrorBoudary';

const RecieptInfoForm = React.lazy(() =>
  Federated.importModule('eRequest', './viewDetailForm'),
);

const RecieptInfo = () => {
  const {t} = useTranslation();
  const navigation = useNavigation();
  const route = useRoute<any>();
  const ticketId = route?.params?.ticketId || '';
  const actionFrom = route?.params?.actionFrom || 'eBLDT';
  const label = route?.params?.label || 'BLDT.infomation_receipt';

  const getListColor = () => {
    switch (actionFrom) {
      case 'QDTHA':
        return ['#072A7E', '#00CEF3'];
      default:
        return ['#B00000', '#F0A04A', '#F2C37F'];
    }
  };
  return (
    <SafeAreaView style={styles.container} edges={['bottom']}>
      <HeaderCM listColor={getListColor()} title={t(label)} />
      <View style={{flex: 1}}>
        <ErrorBoundary name="" navigation={navigation}>
          <React.Suspense fallback={<SplashScreen app="" />}>
            <RecieptInfoForm ticketId={ticketId} />
          </React.Suspense>
        </ErrorBoundary>
      </View>
    </SafeAreaView>
  );
};
export default RecieptInfo;
