import {getConfig} from './httpClient';

export const createQDTHAService = (fetchRequest: any) => ({
  async getListJudgmentDecisions(params: any, body: any) {
    try {
      const endpoint = '/services/thads-qdtha/api/search/judgment-decisions';
      const data = await fetchRequest({
        url: getConfig().BASE_URL_QDTHA + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        params,
        body: JSON.stringify(body),
      });
      const totals = data?.headers.get('x-total-count') ?? 0;
      return Promise.resolve({
        data: data?.data,
        totalData: Number(totals),
      });
    } catch (error) {}
  },

  async judgmentDecisionDetail(id: any) {
    try {
      const endpoint = `/services/thads-qdtha/api/judgment-decisions/${id}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_QDTHA + endpoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {}
  },
  async getMyDYC(
    page: number,
    size: number,
    body: any,
    type: 'authorized' | 'owner',
  ) {
    const endPoint = `/services/thads-qdtha/api/search/requests?page=${page}&size=${size}&sort=createdDate,desc&type=${type}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL_QDTHA + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body) || '{}',
      });
      const totalData = data?.headers.get('x-total-count') || 0;
      return Promise.resolve({
        data: data?.data,
        totalData: totalData,
      });
    } catch (error) {
      Promise.reject(error);
    }
  },
  async getDetailMyDYC(id: string) {
    const endPoint = `/services/thads-qdtha/api/requests/${id}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL_QDTHA + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
  async getDetailMyDYCHistory(id: string) {
    const endPoint = `/services/thads-qdtha/api/log-activities/request-all/${id}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL_QDTHA + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
  async getDocumentReturn(id: string) {
    const endPoint = `/services/thads-qdtha/api/storage-attaches/envelope/${id}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL_QDTHA + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },

  async getDocJudgmentDecision(id: string) {
    const endPoint = `/services/thads-qdtha/api/storage-attaches/judgment-decisions/envelope/${id}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL_QDTHA + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
  async generateNewNumber(id: string) {
    const endPoint = `/services/thads-qdtha/api/officer/requests/regenerate/${id}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL_QDTHA + endPoint,
        method: 'PUT',
        typeOfResponse: 'text',
        params: {
          documentType: 'PND',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
});
