import {getConfig} from './httpClient';

export const createCatalogService = (fetchRequest: any) => ({
  async getAppStatus() {
    try {
      const endpoint =
        '/services/ecategory/api/data/code/APPLICATION_STATUS?page=0&size=100';
      const data = await fetchRequest({
        url: getConfig().BASE_URL_ECATALOG + endpoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {}
  },
});
